INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1660792', 'Battle of Cirta', 'The Battle of Cirta was fought in 203 BC between an army of largely Masaesyli Numidians commanded by their king Syphax and a force of mainly Massylii Numidians led by Masinissa, who was supported by an unknown number of Romans under the legate Gaius Laelius. It took place somewhere to the east of the city of Cirta (modern Constantine) and was part of the Second Punic War.', -203, NULL, NULL, NULL, NULL, NULL, 'year', '203 BCE', 45, 'https://en.wikipedia.org/wiki/Battle_of_Cirta'),
  ('Q11949529', 'Siege of Cirta', 'The siege of Cirta was fought between the rival Numidian kings Adherbal and Jugurtha in 113 BC. They were contesting the throne of Numidia after the death of King Micipsa. Jugurtha invaded Adherbal''s territory, defeated him and besieged him in his capital Cirta.', -112, NULL, NULL, NULL, NULL, NULL, 'year', '112 BCE', 39, 'https://en.wikipedia.org/wiki/Siege_of_Cirta'),
  ('Q2890102', 'Battle of Suthul', 'The Battle of Suthul was one of the confrontations of the Jugurthine War. The battle was fought in 110 BC between the Numidian army, led by King Jugurtha, and the Roman forces, led by Aulus Postumius Albinus.', -110, NULL, NULL, NULL, NULL, NULL, 'year', '110 BCE', 41, 'https://en.wikipedia.org/wiki/Battle_of_Suthul'),
  ('Q619030', 'Battle of the Bagradas River', 'The Battle of the Bagradas (49 BC) occurred near the Bagradas River (the classical name of the Medjerda) in what is now Tunisia on 24 August and was fought between Julius Caesar''s general Gaius Scribonius Curio and the Pompeian Republicans under Publius Attius Varus and King Juba I of Numidia. The result was a crushing defeat for the Caesarean forces and the death of Curio.', -49, 8, 24, NULL, NULL, NULL, 'day', '24 August 49 BCE', 50, 'https://en.wikipedia.org/wiki/Battle_of_the_Bagradas_(49_BC)'),
  ('Q7510087', 'Siege of Hippo Regius', 'The siege of Hippo Regius was a siege from June 430 to August 431, carried out by the Vandals under their king Gaiseric against Roman defenders under Boniface, Count of Africa.', 430, 6, NULL, 431, 8, NULL, 'month', 'June 430 – August 431', 39, 'https://en.wikipedia.org/wiki/Siege_of_Hippo_Regius'),
  ('Q86750701', 'Battle of the Bagradas River', 'The Siege of Carthage took place in c. Easter 536, when dissatisfied Byzantine soldiers revolted against Solomon, the ruler of the Praetorian prefecture of Africa. The administration of Byzantine North Africa was under the magister militum Solomon, after Belisarius had conquered the Vandal Kingdom in the Vandalic War of 534.', 536, NULL, NULL, NULL, NULL, NULL, 'year', '536', 34, 'https://en.wikipedia.org/wiki/Battle_of_the_Bagradas_River_(536)'),
  ('Q2237785', 'Battle of Vescera', 'The Battle of Vescera (modern Biskra in Algeria) was fought in 682 or 683 between the Romano-Berbers of King Kusaila and their Byzantine allies from the Exarchate of Africa against an Umayyad Arab army under Uqba ibn Nafi (the founder of Kairouan). Uqba ibn Nafi had led his men in an expedition across north Africa, eventually reaching the Atlantic Ocean and marching as far south as the Draa and Sous rivers.', 682, NULL, NULL, NULL, NULL, NULL, 'year', '682', 51, 'https://en.wikipedia.org/wiki/Battle_of_Vescera'),
  ('Q22690044', 'Battle of Mamma', 'The Battle of Mamma or the Battle of Mammes (Arabic: معركة ممس) took place at some point between the years 686 and 690 or otherwise before 688. The belligerents were the Arab Muslim forces of the Umayyad Caliphate against the Berbers led by Caecilius of the Kingdom of Altava.', 688, NULL, NULL, NULL, NULL, NULL, 'year', '688', 39, 'https://en.wikipedia.org/wiki/Battle_of_Mamma'),
  ('Q55595759', 'Battle of Meskiana', 'The Battle of Meskiana occurred in North Africa in 698 between the Umayyad forces of Hassan ibn al-Nu''man and Queen Dihya.', 698, NULL, NULL, NULL, NULL, NULL, 'year', '698', 39, 'https://en.wikipedia.org/wiki/Battle_of_Meskiana'),
  ('Q3486030', 'Siege of Tlemcen', 'The siege of Tlemcen from 1299 to 1307 designates all of the operations undertaken by the army of the Marinid sultan, Abu Yaqub Yusuf an-Nasr to seize the city of Tlemcen, the capital of the Zayyanid Kingdom, during the conflict between the Kingdom of Tlemcen and the Marinids. The siege was lifted following the assassination of the Marinid Sultan.', 1299, NULL, NULL, 1307, NULL, NULL, 'year', '1299–1307', 34, 'https://en.wikipedia.org/wiki/Siege_of_Tlemcen_(1299%E2%80%931307)'),
  ('Q3486034', 'Siege of Tlemcen', 'The siege of Tlemcen from 1335 to 1337 was a military operation undertaken by the Marinid Sultan Abu al-Hasan Ali ibn Othman against the capital of the Zayyanid Kingdom. The siege began in 1335, and ended with the fall of the city to the Marinids in 1337.', 1335, NULL, NULL, 1337, NULL, NULL, 'year', '1335–1337', 34, 'https://en.wikipedia.org/wiki/Siege_of_Tlemcen_(1335%E2%80%931337)'),
  ('Q603279', 'Capture of Mers-el-Kébir', 'The Capture of Mers-el-Kébir on September 13, 1505 was the first campaign carried out by the Spanish Empire in its war against the Zayyanid Kingdom of Tlemcen (in modern Algeria). Mers-el-Kébir (Spanish: Mazalquivir) was a roadstead open to the southwest winds, and a refuge for corsairs.', 1505, 9, 13, NULL, NULL, NULL, 'day', '13 September 1505', 45, 'https://en.wikipedia.org/wiki/Capture_of_Mers-el-K%C3%A9bir_(1505)'),
  ('Q104902074', 'Battle of Mers-el-Kébir', 'The Battle of Mers-el-Kébir took place between the Spanish Empire, and the native Kingdom of Tlemcen, near, and around Mers-el-Kébir', 1507, NULL, NULL, NULL, NULL, NULL, 'year', '1507', 34, 'https://en.wikipedia.org/wiki/Battle_of_Mers-el-K%C3%A9bir_(1507)'),
  ('Q28496874', 'Capture of Béjaïa', 'The Spanish Empire captured Béjaïa (also known as Bougie) in 1510, then an emirate ruled by a branch of the Hafsid dynasty. The Spanish lost the city again 45 years later to Salah Rais and the Kingdom of Kuku in the Capture of Bougie (1555).', 1510, 1, 5, NULL, NULL, NULL, 'day', '5 January 1510', 37, 'https://en.wikipedia.org/wiki/Capture_of_B%C3%A9ja%C3%AFa_(1510)'),
  ('Q4188858', 'Capture of Algiers', 'The capture of Algiers in 1516 was accomplished by the brothers Oruç and Hayreddin Barbarossa against Sālim al-Tūmī, the ruler of the city of Algiers, which was followed by an unsuccessful military campaign by the Spanish Empire and the Sheikh of Ténès to overthrow the newly formed Sultanate of Algiers.', 1516, 9, NULL, 1516, 10, NULL, 'month', 'September 1516 – October 1516', 50, 'https://en.wikipedia.org/wiki/Capture_of_Algiers_(1516)'),
  ('Q4090268', 'Fall of Tlemcen', 'The fall of Tlemcen occurred in 1518, when the Ottoman admiral Oruç Barbarossa captured the city of Tlemcen from its sultan, Abu Zayan, the last member of the Banu Zayan lineage. The fall of Tlemcen followed the capture of Ténès, also by Oruç and his brother, Hayreddin.', 1518, 1, NULL, 1518, 5, NULL, 'month', 'January 1518 – May 1518', 50, 'https://en.wikipedia.org/wiki/Fall_of_Tlemcen_(1518)'),
  ('Q3403025', 'Capture of Algiers', 'The capture of Peñón of Algiers was accomplished when the beylerbey of Algiers, Hayreddin Barbarossa, captured the fortress called Peñón of Algiers, on a small islet facing the Algerian city of Algiers from the Habsburg Spaniards.', 1529, 5, 29, NULL, NULL, NULL, 'day', '29 May 1529', 51, 'https://en.wikipedia.org/wiki/Capture_of_Pe%C3%B1%C3%B3n_of_Algiers_(1529)'),
  ('Q109229623', '1790 Oran earthquake', 'The 1790 Oran earthquake occurred on 10 October, striking near the coastal city of Oran in Algeria. The earthquake had an evaluated maximum seismic intensity of VIII–X on the European macroseismic scale (EMS-98).', 1790, 10, 10, NULL, NULL, NULL, 'day', '10 October 1790', 37, 'https://en.wikipedia.org/wiki/1790_Oran_earthquake'),
  ('Q2890049', 'Battle of Staouéli', 'Battle of Staoueli (18 June 1830 – 19 June 1830) was a battle between the Kingdom of France and the Regency of Algiers in western Algiers while France was trying to take control over the capital.', 1830, 6, 19, NULL, NULL, NULL, 'day', '19 June 1830', 41, 'https://en.wikipedia.org/wiki/Battle_of_Staou%C3%A9li'),
  ('Q3317226', 'Invasion of Algiers in 1830', 'The invasion of Algiers was a large-scale military operation by which the Kingdom of France, ruled by King Charles X, invaded and conquered the Regency of Algiers. A diplomatic incident in 1827, the so-called ''Fan Affair'' (''Fly Whisk Incident''), served as a pretext to initiate a blockade against the port of Algiers.', 1830, 6, 14, 1830, 7, 7, 'day', '14 June 1830 – 7 July 1830', 53, 'https://en.wikipedia.org/wiki/Invasion_of_Algiers_(1830)'),
  ('Q2825906', 'Massacre of El Ouffia', 'The massacre of El Ouffia (French: L''affaire d''El Ouffia) took place on 6 April 1832 during the French conquest of Algeria. It was committed against the tribe of El Ouffia near El Harrach by the Troupes Coloniales under Colonel Maximilien Joseph Schauenburg.', 1832, 4, NULL, NULL, NULL, NULL, 'month', 'April 1832', 34, 'https://en.wikipedia.org/wiki/Massacre_of_El_Ouffia'),
  ('Q621362', 'Battle of Macta', 'The Battle of Macta (Arabic: معركة المقطع) was fought on 28 June 1835 between French colonial forces led by General Camille Alphonse Trézel and the forces of Emir ʿAbd al-Qādir, leader of the Emirate of Mascara. It was a major defeat for the French in the early years of the conquest of Algeria, and it marked the first large-scale military success of ʿAbd al-Qādir’s resistance.', 1835, 6, 28, NULL, NULL, NULL, 'day', '28 June 1835', 37, 'https://en.wikipedia.org/wiki/Battle_of_Macta'),
  ('Q3485860', 'Battle of Constantine', 'The 1836 Battle of Constantine was an unsuccessful French attempt to conquer the Algerian city of Constantine. It was part of the siege of Constantine.', 1836, 11, 21, 1836, 11, 24, 'day', '21 November 1836 – 24 November 1836', 37, 'https://en.wikipedia.org/wiki/Battle_of_Constantine'),
  ('Q636772', 'Siege of Constantine', 'The siege of Constantine was a blockade and assault on Constantine in October 1837 by French forces during the French conquest of Algeria. The decisive battle resulted in the collapse of the Beylik of Constantine led by Ahmed Bey.', 1837, 10, 10, 1837, 10, 13, 'day', '10 October 1837 – 13 October 1837', 34, 'https://en.wikipedia.org/wiki/Siege_of_Constantine'),
  ('Q2889297', 'Battle of Mazagran', 'The Battle of Mazagran was a combat between Arab and Berber forces against French troops during the French conquest of Algeria. The small French contingent, holed up in a fortification at Mazagran, near the port city of Mostaganem, withstood several days of assault by `Abd al-Qādir ''s troops.', 1840, 2, NULL, NULL, NULL, NULL, 'month', 'February 1840', 41, 'https://en.wikipedia.org/wiki/Battle_of_Mazagran'),
  ('Q3403872', 'Battle of the Smala', 'The Battle of the Smala took place on 16 May 1843, when the French, led by Henri d''Orléans, Duke of Aumale, raided the personal encampment (Arabic: زمالة zmala) of Algerian resistance leader Emir Abdelkader al-Jazairi while al-Qadir was absent on a raiding expedition. The 500 French cavalrymen surprised the camp defenders, who fired a single volley before scattering.', 1843, 5, 16, NULL, NULL, NULL, 'day', '16 May 1843', 39, 'https://en.wikipedia.org/wiki/Battle_of_the_Smala'),
  ('Q2889977', 'Battle of Sidi-Brahim', 'The Battle of Sidi Brahim, 23 to 25 September 1845, took place during the French conquest of Algeria, near Souahlia in Tlemcen Province. Between 1,000 and 1,200 Algerian irregulars under Emir Abdelkader ambushed a French detachment of around 500 led by Lieutenant-Colonel Lucien de Montagnac.', 1845, 9, 25, 1845, 9, 26, 'day', '25 September 1845 – 26 September 1845', 34, 'https://en.wikipedia.org/wiki/Battle_of_Sidi_Brahim'),
  ('Q16931833', 'Siege of Laghouat', 'The siege of Laghouat in 1852 was an episode of the French pacification of Algeria.', 1852, 11, 21, 1852, 12, 4, 'day', '21 November 1852 – 4 December 1852', 34, 'https://en.wikipedia.org/wiki/Siege_of_Laghouat'),
  ('Q503347', 'Attack on Mers-El-Kebir', 'The attack on Mers-el-Kébir (Battle of Mers-el-Kébir) on 3 July 1940, during the Second World War, was a British naval attack on French Navy ships at the naval base at Mers El Kébir, near Oran, on the coast of French Algeria. The attack was the main part of Operation Catapult, a British plan to neutralise or destroy French ships to prevent them from falling into German hands after the Allied defeat in the Battle of France.', 1940, 7, 3, NULL, NULL, NULL, 'day', '3 July 1940', 66, 'https://en.wikipedia.org/wiki/Attack_on_Mers-el-K%C3%A9bir'),
  ('Q200790', 'Algerian War', 'The Algerian War, also known as the Algerian Revolution, the Franco-Algerian War, or the Algerian War of Independence, was an armed conflict between France and the Algerian National Liberation Front (FLN) from 1954 to 1962, which led to Algeria winning its independence from France. An important decolonization war, it was a complex conflict characterized by guerrilla warfare and war crimes.', 1954, 11, 1, 1962, 9, 9, 'day', '1 November 1954 – 9 September 1962', 81, 'https://en.wikipedia.org/wiki/Algerian_War'),
  ('Q5930951', '1954 Chlef earthquake', 'The 1954 Chlef earthquake struck El Asnam Province in French Algeria on 9 September at 02:04:43 local time. The shock measured 6.7 on the moment magnitude scale and had a maximum Mercalli intensity of XI (Extreme).', 1954, 9, 9, NULL, NULL, NULL, 'day', '9 September 1954', 39, 'https://en.wikipedia.org/wiki/1954_Chlef_earthquake'),
  ('Q6889422', 'Battle of Philippeville', 'The Philippeville massacre, also known as the Battle of Philippeville or the August Offensive, was a series of raids launched on 20 August 1955 on various cities and towns of the Constantine region by FLN insurgents and armed mobs during the Algerian War between France and the Algerian rebels. The raids, which mostly took the form of ethnic riots, resulted in the massacre of several dozens of European settlers, known as pieds-noirs.', 1955, 8, 20, 1955, 8, 25, 'day', '20 August 1955 – 25 August 1955', 39, 'https://en.wikipedia.org/wiki/Philippeville_massacre'),
  ('Q1761043', 'Battle of Algiers', 'The Battle of Algiers, also called the great repression of Algiers, was a campaign fought during the Algerian War. It consisted of urban guerrilla warfare and terrorist attacks carried out by the National Liberation Front (FLN) against the French authorities in Algiers, and by the French authorities, army, and French terrorist organizations against the FLN. Both sides targeted civilians throughout the battle.', 1956, 9, 30, 1957, 10, 9, 'day', '30 September 1956 – 9 October 1957', 50, 'https://en.wikipedia.org/wiki/Battle_of_Algiers_(1956%E2%80%931957)'),
  ('Q123409743', 'Battle of Djbel Bouk''hil', 'The Battle of Djebel Bouk''hil was a major fight in the Algerian War in 1961 when the French intercepted a meeting between FLN commanders, then Besieging the Mountain.', 1961, 9, 17, 1961, 9, 18, 'day', '17 September 1961 – 18 September 1961', 34, 'https://en.wikipedia.org/wiki/Battle_of_Djebel_Bouk''hil_(1961)'),
  ('Q1471139', 'Evian Accords', 'The Évian Accords were a set of declarations between the French Government and the Provisional Government of the Algerian Republic on 18 March 1962 in Évian-les-Bains which outlined the agreements for Algeria''s Independence alongside cooperation with France. The Accords consisted of five chapters which detailed the guarantees and principals of this Independence.', 1962, 3, 18, NULL, NULL, NULL, 'day', '18 March 1962', 65, 'https://en.wikipedia.org/wiki/%C3%89vian_Accords'),
  ('Q2546598', 'Oran massacre of 1962', 'The Oran massacre of 1962 was a massacre of Pied-Noir and European settlers by Front de libération nationale (FLN) troops and Algerian civilians in Oran, Algeria. Between 95 and 365 people were killed in the massacre from 5–7 July, 1962.', 1962, 7, 5, NULL, NULL, NULL, 'day', '5 July 1962', 41, 'https://en.wikipedia.org/wiki/Oran_massacre_of_1962'),
  ('Q2888071', 'Battle of Bab El Oued', 'The Battle of Bab el Oued (French: Bataille de Bab el Oued) was an armed confrontation which occurred during the latter stages of the Algerian War (1954–1962) between the French Army and the Organisation armée secrète (OAS) which opposed Algerian independence. It took place in Bab El Oued, then a working-class European quarter of Algiers, from 23 March to 6 April 1962.', 1962, 3, 23, 1962, 4, 6, 'day', '23 March 1962 – 6 April 1962', 39, 'https://en.wikipedia.org/wiki/Battle_of_Bab_El_Oued'),
  ('Q3091166', '1962 Isly massacre', 'The 1962 Isly massacre was an incident during the Algerian War when French Army soldiers opened fire on a crowd of Pied-Noir demonstrators marching in support of France''s control over Algeria on 26 March 1962. Following the army''s blockade of Bab El Oued, which served as the headquarters of the Organisation armée secrète (OAS), the OAS called for massive demonstrations to force an end to the blockade.', 1962, 3, 26, NULL, NULL, NULL, 'day', '26 March 1962', 34, 'https://en.wikipedia.org/wiki/1962_Isly_massacre'),
  ('Q1891008', 'Sand War', 'The Sand War (Arabic: حَرْبُ الرِّمَال, romanized: Ḥarb ar-Rimāl) was a border conflict between Algeria and Morocco fought from September 25 to October 30, 1963, although a formal peace treaty was not signed until February 20, 1964. It resulted largely from the Moroccan government''s claim to portions of Algeria''s Tindouf and Béchar provinces.', 1963, 9, 25, 1964, 2, 20, 'day', '25 September 1963 – 20 February 1964', 63, 'https://en.wikipedia.org/wiki/Sand_War'),
  ('Q2999015', '1965 Algerian coup d''état', 'The 1965 Algerian coup d''état, also called the Revolutionary Correction, brought Colonel Houari Boumédiène to power as Chairman of the Revolutionary Council in Algeria. The bloodless coup d''état saw Algeria''s first President, Ahmed Ben Bella, arrested and his closest supporters imprisoned by Boumédiène and his allies, principally in the People''s National Army, the country’s armed forces.', 1965, 6, 19, NULL, NULL, NULL, 'day', '19 June 1965', 37, 'https://en.wikipedia.org/wiki/1965_Algerian_coup_d''%C3%A9tat'),
  ('Q1071266', 'Berber Spring', 'The Berber Spring (Tamazight: Tafsut Imaziɣen or simply Tafsut for "Spring") was a period of political protest and civil activism in 1980, claiming recognition of the Amazigh identity and language in Algeria, with events mainly taking place in Kabylia and Algiers.', 1980, 4, 20, 1980, 4, 20, 'day', '20 April 1980', 45, 'https://en.wikipedia.org/wiki/Berber_Spring'),
  ('Q142529', 'Algerian Civil War', 'The Algerian Civil War (Arabic: الحرب الأهلية الجزائرية, romanized: al-Ḥarb al-Ahlīyah al-Jazāʼirīyah), known in Algeria as the Black Decade (Arabic: العشرية السوداء, romanized: al-ʻAshrīyah al-Sawdāʼ; French: La décennie noire), was a civil war fought between the Algerian government and various Islamist rebel groups from 11 January 1992 (following a coup negating an Islamist electoral victory) to 8 February 2002. The war began slowly; it initially appeared that the government had succeeded in crushing the Islamist movement, but armed groups emerged to declare violent jihad, and by 1994…', 1992, 1, 11, 2002, 2, 8, 'day', '11 January 1992 – 8 February 2002', 68, 'https://en.wikipedia.org/wiki/Algerian_Civil_War'),
  ('Q2637132', 'Assassination of the monks of Tibhirine', 'On the night of 26–27 March 1996, seven monks of the Trappist order from the Our Lady of the Atlas Abbey of Tibhirine near Médéa, Algeria, were kidnapped during the Algerian Civil War. They were held for two months, and found dead in late May 1996.', 1996, 3, NULL, NULL, NULL, NULL, 'month', 'March 1996', 55, 'https://en.wikipedia.org/wiki/Murder_of_the_monks_of_Tibhirine'),
  ('Q507359', 'Bentalha massacre', 'In the village of Bentalha (Arabic: بن طلحة), located 15 km (9.3 mi) south of Algiers, an incident occurred on the night of 22–23 September 1997, where a significant number of villagers were killed by armed guerrillas. According to Amnesty International, over 200 villagers were killed.', 1997, 9, NULL, 1997, 9, 23, 'month', 'September 1997 – 23 September 1997', 43, 'https://en.wikipedia.org/wiki/Bentalha_massacre'),
  ('Q2738493', 'Thalit massacre', 'The Thalit massacre took place in Thalit village (Médéa, near Ksar el Boukhari), some 70 km from Algiers, on April 3–4, 1997 during the Algerian Civil War. Fifty-two out of the 53 inhabitants were killed by having their throats cut during a 12-hour rampage.', 1997, 4, 4, NULL, NULL, NULL, 'day', '4 April 1997', 39, 'https://en.wikipedia.org/wiki/Thalit_massacre'),
  ('Q3069286', 'Haouch Khemisti massacre', 'The Haouch Khemisti massacre took place before dawn on April 22, 1997, in the Algerian village of Haouch Mokhfi Khemisti, some 25 km south of Algiers near Bougara. An armed group killed 93 villagers in a 3 hour long attack because they refused to "collaborate", since armed groups depended on the aid of citizens who provide food, money and other necessities for their survival.', 1997, 4, 22, NULL, NULL, NULL, 'day', '22 April 1997', 37, 'https://en.wikipedia.org/wiki/Haouch_Khemisti_massacre'),
  ('Q3133675', 'Beni Ali massacre', 'The Beni Ali massacre took place in the mountain hamlet of Beni Ali, 40 miles (64 km) south of Algiers near Chrea, on 26 August 1997. Sixty-four (according to The New York Times and CNN) or 100 people (according to Amnesty International) were killed in a terrorist attack.', 1997, 8, 26, NULL, NULL, NULL, 'day', '26 August 1997', 39, 'https://en.wikipedia.org/wiki/Beni_Ali_massacre'),
  ('Q5209543', 'Daïat Labguer massacre', 'The Daïat Labguer (M''sila) massacre took place on June 16, 1997, near M''sila, 300 km southeast of Algiers. The massacre came less than two weeks after parliamentary elections in the hamlet of Daïat Labguer (M''sila) (also spelled Dairat Labguar, Dairat Lebguar, Daïat Labguer, Daïret Lebguer, Dairet Lebguer).', 1997, 6, 16, NULL, NULL, NULL, 'day', '16 June 1997', 37, 'https://en.wikipedia.org/wiki/Da%C3%AFat_Labguer_(M''sila)_massacre'),
  ('Q6470690', 'Si Zerrouk massacre', 'The Si Zerrouk massacre took place in the Si Zerrouk neighborhood in the south of Larbaa in Algeria on 27 July 1997. About 50 people were killed.', 1997, 7, 27, NULL, NULL, NULL, 'day', '27 July 1997', 37, 'https://en.wikipedia.org/wiki/Si_Zerrouk_massacre'),
  ('Q6470701', 'Souhane massacre', 'The largest of the Souhane massacres occurred in the small mountain town of Souhane (about 25 km south of Algiers, between Larbaa and Tablat) on 20–21 August 1997. 64 people were killed, and 15 women were kidnapped; the resulting terror triggered a mass exodus, reducing the town''s population down from 4000 before the massacre to just 103 in 2002.', 1997, 8, 20, NULL, NULL, NULL, 'day', '20 August 1997', 39, 'https://en.wikipedia.org/wiki/Souhane_massacre'),
  ('Q6470770', 'Omaria massacre', 'The largest Omaria massacre took place on 23 April 1997 in the Algerian village of El Omaria near Médéa, south of Algiers. Attackers armed with knives, sabers, and guns killed 42 people - including 17 women and 3 babies - in 3 hours, mutilating and sometimes burning the bodies.', 1997, 4, 23, NULL, NULL, NULL, 'day', '23 April 1997', 39, 'https://en.wikipedia.org/wiki/Omaria_massacre'),
  ('Q6470782', 'Rais massacre', 'The Rais massacre was a massacre carried out during the Algerian civil war. It took place on 28 August 1997 and was conducted by the Armed Islamic Group of Algeria against the village of Rais, near Sidi Moussa and south of Algiers.', 1997, 8, 29, NULL, NULL, NULL, 'day', '29 August 1997', 37, 'https://en.wikipedia.org/wiki/Rais_massacre'),
  ('Q27559', 'Black Spring', 'The Black Spring (Kabyle: Tafsut Taberkant) was a series of protests and political demonstrations by Kabyle activists in the Kabylie region of Algeria in 2001, which were met by repressive and violent police measures and became a potent symbol of Kabyle discontent with the national government. The protests took place against a backdrop of long-standing cultural marginalization of the Highlander Kabyle, a homogeneous Berber linguistic group in Algeria (Berber speakers form some 25%–35% of the total population, although exact numbers are disputed) despite the most rigid government-sponsored…', 2001, 4, 18, 2001, 6, 14, 'day', '18 April 2001 – 14 June 2001', 41, 'https://en.wikipedia.org/wiki/Black_Spring_(Algeria)'),
  ('Q116688', '2003 Boumerdès earthquake', 'The 2003 Boumerdès earthquake occurred on May 21 at 19:44:21 local time in northern Algeria. The shock had a moment magnitude of 6.8 and a maximum Mercalli intensity of X (Extreme).', 2003, 5, 21, NULL, NULL, NULL, 'day', '21 May 2003', 50, 'https://en.wikipedia.org/wiki/2003_Boumerd%C3%A8s_earthquake'),
  ('Q472238', '2010–2012 Algerian protests', 'The 2010–2012 Algerian protests were a series of protests taking place throughout Algeria, lasting from 28 December 2010 to 10 January 2012. The protests were inspired by similar protests across the Middle East and North Africa.', 2010, 12, 28, 2012, 1, 10, 'day', '28 December 2010 – 10 January 2012', 64, 'https://en.wikipedia.org/wiki/2010%E2%80%932012_Algerian_protests'),
  ('Q4616584', '2010 Algeria earthquake', 'The 2010 Beni-Ilmane earthquakes began 14 May at 12:29:22 UTC, when a Mw 5.3 strike-slip earthquake occurred in Northern Algeria. With a maximum EMS-98 intensity of VII (Damaging), it was the first in a sequence of three shocks that affected the Bouïra Province over a ten-day period.', 2010, 5, 14, NULL, NULL, NULL, 'day', '14 May 2010', 37, 'https://en.wikipedia.org/wiki/2010_Beni-Ilmane_earthquakes'),
  ('Q3211577', 'In Aménas hostage crisis', 'The In Amenas hostage crisis began on 16 January 2013, when al-Qaeda-linked terrorists affiliated with a brigade led by Mokhtar Belmokhtar took expat hostages at the Tigantourine gas facility near In Amenas, Algeria. One of Belmokhtar''s senior lieutenants, Abdul al Nigeri, led the attack and was among the terrorists killed.', 2013, 1, 16, NULL, NULL, NULL, 'day', '16 January 2013', 62, 'https://en.wikipedia.org/wiki/In_Amenas_hostage_crisis'),
  ('Q15726739', '2014 Algerian Air Force C-130 crash', 'On 11 February 2014, a C-130 Hercules military transport aircraft of the Algerian Air Force, carrying 74 passengers and 4 crew members, crashed into Djebel Fertas mountain near Aïn Kercha, Algeria. Only one person survived.', 2014, 2, 11, NULL, NULL, NULL, 'day', '11 February 2014', 57, 'https://en.wikipedia.org/wiki/2014_Algerian_Air_Force_C-130_crash'),
  ('Q61829297', '2019–2021 Algerian protests', 'The 2019–2021 Algerian protests, also called Revolution of Smiles or Hirak (Arabic: الحِرَاك, romanized: al-Ḥirāk, lit. ''The movement''), began on 16 February 2019, six days after Abdelaziz Bouteflika announced his candidacy for a fifth presidential term in a signed statement. These protests, without precedent since the Algerian Civil War, were peaceful and led the military to insist on Bouteflika''s immediate resignation, which took place on 2 April 2019.', 2019, 2, 16, NULL, NULL, NULL, 'day', '16 February 2019', 57, 'https://en.wikipedia.org/wiki/Hirak_(Algeria)'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic');
